@import "tailwindcss";

@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

:root {
  --bg: #f6f8fc;
  --surface: #ffffff;
  --row-read: #f2f6fc;
  --row-unread: #ffffff;
  --hover: rgba(68, 71, 70, 0.08);
  --hover-strong: rgba(68, 71, 70, 0.14);
  --text: #1f1f1f;
  --text-2: #444746;
  --text-3: #5f6368;
  --border: #e3e3e3;
  --divider: rgba(100, 121, 143, 0.12);
  --nav-active: #d3e3fd;
  --nav-active-text: #001d35;
  --compose: #c2e7ff;
  --compose-hover: #b3dcf5;
  --compose-text: #001d35;
  --primary: #0b57d0;
  --primary-hover: #0a4fbd;
  --on-primary: #ffffff;
  --selected-row: #c2dbff;
  --search: #e9eef6;
  --search-focus: #ffffff;
  --chip: #e8eaed;
  --tooltip: #3c4043;
  --menu: #ffffff;
  --shadow: 0 1px 2px 0 rgba(60, 64, 67, 0.3), 0 2px 6px 2px rgba(60, 64, 67, 0.15);
  --shadow-row: inset 1px 0 0 #dadce0, inset -1px 0 0 #dadce0, 0 1px 2px 0 rgba(60, 64, 67, 0.3), 0 1px 3px 1px rgba(60, 64, 67, 0.15);
  --star: #f4b400;
  --danger: #d93025;
  --compose-head: #f2f6fc;
  --quote: #5f6368;
  color-scheme: light;
}

[data-theme="dark"] {
  --bg: #111316;
  --surface: #1c1e21;
  --row-read: #1c1e21;
  --row-unread: #25272b;
  --hover: rgba(227, 227, 227, 0.08);
  --hover-strong: rgba(227, 227, 227, 0.14);
  --text: #e3e3e3;
  --text-2: #c4c7c5;
  --text-3: #9aa0a6;
  --border: #3c4043;
  --divider: rgba(227, 227, 227, 0.1);
  --nav-active: #004a77;
  --nav-active-text: #c2e7ff;
  --compose: #004a77;
  --compose-hover: #005a91;
  --compose-text: #c2e7ff;
  --primary: #a8c7fa;
  --primary-hover: #bcd4fb;
  --on-primary: #062e6f;
  --selected-row: #1f3a5f;
  --search: #2a2c30;
  --search-focus: #36383c;
  --chip: #3c4043;
  --tooltip: #e3e3e3;
  --menu: #2a2c30;
  --shadow: 0 1px 3px 0 rgba(0, 0, 0, 0.6), 0 4px 8px 3px rgba(0, 0, 0, 0.3);
  --shadow-row: inset 1px 0 0 #3c4043, inset -1px 0 0 #3c4043, 0 1px 2px 0 rgba(0, 0, 0, 0.6), 0 1px 3px 1px rgba(0, 0, 0, 0.3);
  --star: #fdd663;
  --danger: #f28b82;
  --compose-head: #2a2c30;
  --quote: #9aa0a6;
  color-scheme: dark;
}

@theme inline {
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-row-read: var(--row-read);
  --color-row-unread: var(--row-unread);
  --color-hover: var(--hover);
  --color-hover-strong: var(--hover-strong);
  --color-ink: var(--text);
  --color-ink-2: var(--text-2);
  --color-ink-3: var(--text-3);
  --color-line: var(--border);
  --color-divider: var(--divider);
  --color-nav-active: var(--nav-active);
  --color-nav-active-ink: var(--nav-active-text);
  --color-compose: var(--compose);
  --color-compose-hover: var(--compose-hover);
  --color-compose-ink: var(--compose-text);
  --color-primary: var(--primary);
  --color-primary-hover: var(--primary-hover);
  --color-on-primary: var(--on-primary);
  --color-selected: var(--selected-row);
  --color-search: var(--search);
  --color-search-focus: var(--search-focus);
  --color-chip: var(--chip);
  --color-menu: var(--menu);
  --color-star: var(--star);
  --color-danger: var(--danger);
  --color-compose-head: var(--compose-head);
  --shadow-float: var(--shadow);
  --shadow-rowhover: var(--shadow-row);
  --font-sans: "Google Sans Text", "Google Sans", Roboto, -apple-system, BlinkMacSystemFont, "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --font-display: "Google Sans", "Product Sans", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow: hidden;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: default;
}

*:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: -2px;
  border-radius: 4px;
}

.scroll-thin {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}
.scroll-thin:hover {
  scrollbar-color: rgba(128, 134, 139, 0.45) transparent;
}

.no-scrollbar {
  scrollbar-width: none;
}
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

/* Message body typography */
.mail-body {
  font-size: 14px;
  line-height: 1.55;
  color: var(--text);
  overflow-wrap: anywhere;
}
.mail-body p {
  margin: 0 0 0.9em;
}
.mail-body p:last-child {
  margin-bottom: 0;
}
.mail-body ul,
.mail-body ol {
  padding-left: 1.5em;
  margin: 0 0 0.9em;
}
.mail-body ul {
  list-style: disc;
}
.mail-body ol {
  list-style: decimal;
}
.mail-body a {
  color: var(--primary);
  text-decoration: underline;
}
.mail-body h2 {
  font-weight: 600;
}
.mail-body blockquote {
  margin: 0.5em 0 0.5em 0.4em;
  padding-left: 1em;
  border-left: 1px solid #ccc;
  color: var(--quote);
}
.mail-body [data-quote-header] {
  color: var(--quote);
  margin: 0.4em 0;
}
.mail-body img {
  max-width: 100%;
}

[contenteditable][data-placeholder]:empty::before {
  content: attr(data-placeholder);
  color: var(--text-3);
  pointer-events: none;
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(4px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.anim-pop {
  animation: pop-in 0.14s cubic-bezier(0.2, 0, 0, 1);
}
.anim-slide {
  animation: slide-up 0.22s cubic-bezier(0.2, 0, 0, 1);
}
.anim-fade {
  animation: fade-in 0.18s ease-out;
}
.anim-spin {
  animation: spin 0.8s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

@media print {
  body {
    overflow: visible;
    background: white;
  }
  .no-print {
    display: none !important;
  }
  .print-area {
    position: static !important;
    overflow: visible !important;
    height: auto !important;
  }
}

