html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow: hidden;
}

button {
  cursor: pointer;
}

button:disabled {
  cursor: default;
}

*:focus-visible {
  outline: 2px solid var(--primary);
  outline-offset: -2px;
  border-radius: 4px;
}

.scroll-thin {
  scrollbar-width: thin;
  scrollbar-color: transparent transparent;
}
.scroll-thin:hover {
  scrollbar-color: rgba(128, 134, 139, 0.45) transparent;
}

.no-scrollbar {
  scrollbar-width: none;
}
.no-scrollbar::-webkit-scrollbar {
  display: none;
}

/* Message body typography */
.mail-body {
  font-size: 14px;
  line-height: 1.55;
  color: var(--text);
  overflow-wrap: anywhere;
}
.mail-body p {
  margin: 0 0 0.9em;
}
.mail-body p:last-child {
  margin-bottom: 0;
}
.mail-body ul,
.mail-body ol {
  padding-left: 1.5em;
  margin: 0 0 0.9em;
}
.mail-body ul {
  list-style: disc;
}
.mail-body ol {
  list-style: decimal;
}
.mail-body a {
  color: var(--primary);
  text-decoration: underline;
}
.mail-body h2 {
  font-weight: 600;
}
.mail-body blockquote {
  margin: 0.5em 0 0.5em 0.4em;
  padding-left: 1em;
  border-left: 1px solid #ccc;
  color: var(--quote);
}
.mail-body [data-quote-header] {
  color: var(--quote);
  margin: 0.4em 0;
}
.mail-body img {
  max-width: 100%;
}

[contenteditable][data-placeholder]:empty::before {
  content: attr(data-placeholder);
  color: var(--text-3);
  pointer-events: none;
}

@keyframes pop-in {
  from {
    opacity: 0;
    transform: translateY(4px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(16px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
@keyframes fade-in {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}
.anim-pop {
  animation: pop-in 0.14s cubic-bezier(0.2, 0, 0, 1);
}
.anim-slide {
  animation: slide-up 0.22s cubic-bezier(0.2, 0, 0, 1);
}
.anim-fade {
  animation: fade-in 0.18s ease-out;
}
.anim-spin {
  animation: spin 0.8s linear infinite;
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

@media print {
  body {
    overflow: visible;
    background: white;
  }
  .no-print {
    display: none !important;
  }
  .print-area {
    position: static !important;
    overflow: visible !important;
    height: auto !important;
  }
}

