    const above = r.top - offset - 8;
    let top: number;
    let maxHeight: number;
    if (h <= below || below >= above) {
      top = r.bottom + offset;
      maxHeight = below;
    } else {
      maxHeight = above;
      top = Math.max(8, r.top - offset - Math.min(h, above));
    }
