              >
                {st === "all" && <Check size={12} strokeWidth={4} />}
                {st === "some" && <Minus size={12} strokeWidth={4} />}
              </span>
              <span className="h-2.5 w-2.5 rounded-full" style={{ background: l.color }} />
              <span className="truncate">{l.name}</span>
            </button>
          );
        })}
      </div>
      <MenuDivider />
      {q.trim() && !exact && (
        <MenuItem
          icon={<Plus size={18} />}
          label={`"${q.trim()}" (create new)`}
          onClick={() => {
            const id = createLabel(q.trim());
            applyLabels(ids, [id], []);
            onDone();
          }}
        />
      )}
      {changed ? (
        <MenuItem label={<span className="font-medium text-primary">Apply</span>} onClick={apply} />
      ) : (
        !q.trim() && (
          <MenuItem
            icon={<Plus size={18} />}
            label="Create new"
            onClick={() => {
              const name = prompt("New label name");
              if (name?.trim()) {
                const id = createLabel(name.trim());
