      <div className="ml-auto flex items-center gap-1">
        <IconButton tip="Keyboard shortcuts" onClick={() => set({ shortcutsOpen: true })}>
          <HelpCircle size={22} />
        </IconButton>
        <IconButton tip="Settings" onClick={() => set({ settingsOpen: true })}>
          <Settings size={22} />
