              <Trash2 size={18} />
            </IconButton>
            <IconButton size="sm" tip={t.unread ? "Mark as read" : "Mark as unread"} onClick={() => a().setUnread([t.id], !t.unread, true)}>
              {t.unread ? <MailOpen size={18} /> : <Mail size={18} />}
            </IconButton>
            {!t.trashed && !t.spam && (
              <IconButton size="sm" tip="Snooze" onClick={snooze.open}>
