              className="flex h-8 max-w-[190px] items-center gap-2 rounded-full border border-line bg-surface px-3 text-[13px] text-ink-2 hover:bg-hover"
            >
              <AttachmentIcon a={att} />
              <span className="truncate">{att.name}</span>
