@import "tailwindcss";

@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

:root {
  --bg: #f6f8fc;
  --surface: #ffffff;
  --row-read: #f2f6fc;
  --row-unread: #ffffff;
  --hover: rgba(68, 71, 70, 0.08);
  --hover-strong: rgba(68, 71, 70, 0.14);
  --text: #1f1f1f;
  --text-2: #444746;
  --text-3: #5f6368;
  --border: #e3e3e3;
  --divider: rgba(100, 121, 143, 0.12);
  --nav-active: #d3e3fd;
  --nav-active-text: #001d35;
  --compose: #c2e7ff;
  --compose-hover: #b3dcf5;
  --compose-text: #001d35;
  --primary: #0b57d0;
  --primary-hover: #0a4fbd;
  --on-primary: #ffffff;
  --selected-row: #c2dbff;
  --search: #e9eef6;
  --search-focus: #ffffff;
  --chip: #e8eaed;
  --tooltip: #3c4043;
  --menu: #ffffff;
  --shadow: 0 1px 2px 0 rgba(60, 64, 67, 0.3), 0 2px 6px 2px rgba(60, 64, 67, 0.15);
