  color-scheme: light;
}

[data-theme="dark"] {
  --bg: #111316;
  --surface: #1c1e21;
  --row-read: #1c1e21;
  --row-unread: #25272b;
  --hover: rgba(227, 227, 227, 0.08);
  --hover-strong: rgba(227, 227, 227, 0.14);
  --text: #e3e3e3;
  --text-2: #c4c7c5;
  --text-3: #9aa0a6;
  --border: #3c4043;
  --divider: rgba(227, 227, 227, 0.1);
