  --compose-head: #2a2c30;
  --quote: #9aa0a6;
  color-scheme: dark;
}

@theme inline {
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-row-read: var(--row-read);
  --color-row-unread: var(--row-unread);
  --color-hover: var(--hover);
