            >
              <AttachmentIcon a={att} />
              <span className="truncate">{att.name}</span>
            </button>
          ))}
          {atts.length > 3 && (
            <span className="flex h-8 items-center rounded-full border border-line px-3 text-[13px] text-ink-2">+{atts.length - 3}</span>
          )}
