              e.stopPropagation();
              a().setStarred([t.id], !t.starred);
            }}
            className="-mr-2 flex h-9 w-9 shrink-0 items-center justify-center"
          >
            <Star size={20} className={t.starred ? "fill-star text-star" : "text-ink-3"} />
