      ),
      attachments: [],
      updatedAt: now - 3 * time.HOUR,
      scheduledAt: nextMorning(now),
    },
  };

  return { threads, drafts, labels: seedLabels };
}

function nextMorning(now: number) {
  const d = new Date(now + time.DAY);
  d.setHours(8, 0, 0, 0);
  return d.getTime();
}

